async function run() {
  const tema = params.tema.trim();
  const quantidade = Math.min(10, Math.max(1, Math.round(params.quantidade)));
  const enviados = state.get("enviados") || [];
  const resultados = await web.search({query: tema + " novidades da semana", count: 10});

  const escolhidos = [];
  for (const r of resultados) {
    if (escolhidos.length >= quantidade) break;
    if (!r.url || enviados.indexOf(r.url) >= 0) continue;
    const j = await judge.relevante({tema: tema, title: r.title, url: r.url, snippet: r.snippet});
    if (j.p >= 0.5) escolhidos.push(r);
  }

  if (escolhidos.length === 0) {
    log("Nenhum resultado novo e relevante sobre " + tema + ".");
    return;
  }

  const linhas = escolhidos.map(function (r) { return "• " + r.title + " — " + r.url; });
  await notify.send({text: "🔎 " + tema + " nesta semana:\n" + linhas.join("\n")});
  state.set("enviados", enviados.concat(escolhidos.map(function (r) { return r.url; })).slice(-100));
}
